get_product_stock.code:
import (
	"fmt"
)

resp, err := client.Products().GetProductStock(ctx, 101, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
fmt.Println(body["available_stock"])
for _, row := range body["locations"].([]any) {
	location := row.(map[string]any)
	fmt.Println(location["warehouse"], location["warehouse_name"], location["stock"], location["is_default"])
}

